// Writes src/main/update/updateToken.generated.js from the GH_UPDATE_TOKEN build
// variable (a read-only GitHub token used by the installed app to look for updates).
// The generated file is git-ignored and packed into the app. The token is never
// printed. `--require` (used by `npm run release`) fails the build when it is missing.
const fs = require('fs');
const path = require('path');

const target = path.join(__dirname, '..', 'src', 'main', 'update', 'updateToken.generated.js');
const token = (process.env.GH_UPDATE_TOKEN || '').trim();
const required = process.argv.includes('--require');

if (!token) {
  if (required) {
    console.error('\nGH_UPDATE_TOKEN is not set.');
    console.error('A release build must contain the read-only update token, or the installed app could never find updates.');
    console.error('Set the GH_UPDATE_TOKEN environment variable (a read-only token for the repository), restart the terminal/VS Code, and run the release again.\n');
    process.exit(1);
  }
  console.log('GH_UPDATE_TOKEN is missing: building WITHOUT an update token (this build cannot check for updates).');
}

if (/[^\x21-\x7e]/.test(token)) {
  console.error('GH_UPDATE_TOKEN contains characters a token cannot have (spaces, quotes or line breaks). Check the variable.');
  process.exit(1);
}

const body =
  '// GENERATED by scripts/write-update-token.js at build time. Git-ignored. Do not edit or commit.\n' +
  `module.exports = { token: ${token ? JSON.stringify(token) : 'null'} };\n`;
fs.writeFileSync(target, body, 'utf8');
console.log(`Update token: ${token ? 'included in this build' : 'not included'}.`);
